// Patches the v5 table with the K1 n-ok title from t8v5. Does not overwrite v5.
// Do not edit this file after it has run.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const src = JSON.parse(readFileSync(resolve('work/out/accept-table-t8-v5.json'), 'utf8'));
const OLD = '19a0f247d22625e54bb1ea773998e8886a8591151390eb27af9b5d4ac6e3ea69';
const SHOOT = '9112224ec051d885fc69664e35ebd0fccef208287eee912bf9792abe560300c0';
const DIAL = 'f3e460f19a599a9059655304852b53b15fbbf81cefb3f90b6325e736712c23ca';
const halfUp3 = JSON.parse(JSON.stringify(src.presets.halfSingle));
halfUp3.k5962 = halfUp3.k5962.slice();
halfUp3.k5962[0] = 175;
halfUp3.k88b2 = [175];
src.presets.halfUp3 = halfUp3;
src.table = 'accept-table-t8-v6';
let after = false;
const changed = [];
for (const step of src.steps) {
  if (step.id === 'n-ok') after = true;
  if (after && step.expect.title === OLD) {
    step.expect.title = SHOOT;
    changed.push(step.id);
  }
  if (step.id === 'n2-up') {
    step.expect.title = DIAL;
    step.expect.half = { preset: 'halfUp3' };
  }
}
writeFileSync(resolve('work/out/accept-table-t8-v6.json'), JSON.stringify(src, null, 2) + '\n');
process.stdout.write(JSON.stringify({ ok: true, changed, n2: halfUp3.k5962[0] }) + '\n');
